}

/** 结构说明（自动提取）：handoffStreamedSaveState；输入 cellUuid、value；直接调用 saveHandoffs.has、Error、validatedHandoff、reduce、handoffBytes.values 等；包含显式抛错路径。 */ function handoffStreamedSaveState(cellUuid: string, value: unknown): void {
