/** 结构说明（自动提取）：peekStreamedSaveState；输入 key；直接调用 saveHandoffs.get、structuredClone。 */ function peekStreamedSaveState(key: string): unknown { const value = saveHandoffs.get(key); return value === undefined ? undefined : structuredClone(value) }
