/** 结构说明（自动提取）：retryWorldStreaming；输入 cellUuid；直接调用 suspended.keys、suspended.delete、snapshots.get、settledTargets.get；写入 snapshot.error、snapshot.status；包含循环处理。 */ function retryWorldStreaming(cellUuid?: string): void { for (const uuid of suspended.keys()) if (!cellUuid || uuid === cellUuid) { suspended.delete(uuid); const snapshot = snapshots.get(uuid); if (snapshot) { snapshot.error = ''; snapshot.status = settledTargets.get(uuid) ?? 'Unloaded' } } }
