  private readonly token = {}
  private readonly lease: WorldStreamingDiagnosticLease
  private readonly runtime: WorldStreamingRuntime
  private closed = false
  private activationPending: boolean
  constructor(readonly world: WorldStreamingWorld, readonly lifecycle: StreamLifecycleOwner, ports: WorldStreamingPorts, readonly state: WorldStreamingState = createInitialWorldStreamingState(), lease?: WorldStreamingDiagnosticLease) {
    if (!world || !Array.isArray(world.entities)) throw new Error('STREAM_WORLD_REQUIRED')
