  }
  handoffStreamedSaveState(...args: Parameters<WorldStreamingRuntime['handoffStreamedSaveState']>): ReturnType<WorldStreamingRuntime['handoffStreamedSaveState']> {
    this.requireOpen()
    return this.runtime.handoffStreamedSaveState(...args)
  }
  consumeStreamedSaveState(...args: Parameters<WorldStreamingRuntime['consumeStreamedSaveState']>): ReturnType<WorldStreamingRuntime['consumeStreamedSaveState']> {
    this.requireOpen()
    return this.runtime.consumeStreamedSaveState(...args)
  }
  captureStreamCellState(...args: Parameters<WorldStreamingRuntime['captureStreamCellState']>): ReturnType<WorldStreamingRuntime['captureStreamCellState']> {
