  }
  exportWorldStreamingHandoffs(...args: Parameters<WorldStreamingRuntime['exportWorldStreamingHandoffs']>): ReturnType<WorldStreamingRuntime['exportWorldStreamingHandoffs']> {
    this.requireOpen()
