  }
  peekStreamedSaveState(...args: Parameters<WorldStreamingRuntime['peekStreamedSaveState']>): ReturnType<WorldStreamingRuntime['peekStreamedSaveState']> {
    this.requireOpen()
    return this.runtime.peekStreamedSaveState(...args)
  }
  cancelWorldStreaming(...args: Parameters<WorldStreamingRuntime['cancelWorldStreaming']>): ReturnType<WorldStreamingRuntime['cancelWorldStreaming']> {
    this.requireOpen()
    return this.runtime.cancelWorldStreaming(...args)
  }
  retryWorldStreaming(...args: Parameters<WorldStreamingRuntime['retryWorldStreaming']>): ReturnType<WorldStreamingRuntime['retryWorldStreaming']> {
    this.requireOpen()
    return this.runtime.retryWorldStreaming(...args)
  }
  shiftStreamingOrigin(...args: Parameters<WorldStreamingRuntime['shiftStreamingOrigin']>): ReturnType<WorldStreamingRuntime['shiftStreamingOrigin']> {
    this.requireOpen()
    return this.runtime.shiftStreamingOrigin(...args)
  }
  resetWorldStreaming(...args: Parameters<WorldStreamingRuntime['resetWorldStreaming']>): ReturnType<WorldStreamingRuntime['resetWorldStreaming']> {
    this.requireOpen()
